/**
 * 二维平面几何计算（整数坐标，单位米）。仅用于本题模拟，不用于真实飞行。
 * 所有判定均按闭区间处理：点落在边界上、线段仅接触边界都算相交。
 */
public final class Geometry {

    private Geometry() {
    }

    /** 平面整数点。 */
    public record Point(int x, int y) {
    }

    /** 非退化轴对齐闭矩形。 */
    public record Rect(int xMin, int yMin, int xMax, int yMax) {
    }

    /** 点是否位于闭矩形内（含边界）。骨架阶段返回 false，后续实现。 */
    public static boolean pointInside(Point p, Rect r) {
        return false;
    }

    /**
     * 线段 p0-p1 是否与闭矩形相交（含端点在矩形内、穿越、仅接触边界）。
     * 骨架阶段返回 false，后续实现。
     */
    public static boolean segmentIntersects(Point p0, Point p1, Rect r) {
        return false;
    }

    /**
     * 折线（按顺序连接的点列，端点重复也算）是否与闭矩形相交。
     * 骨架阶段返回 false，后续实现。
     */
    public static boolean polylineIntersects(java.util.List<Point> points, Rect r) {
        return false;
    }
}

